function compressProcess(samples, opts){
  opts = opts || {};
  var thr = opts.threshold != null ? opts.threshold : -20;   // dB
  var ratio = opts.ratio != null ? opts.ratio : 4;
  var makeup = opts.makeup != null ? opts.makeup : 0;        // dB
  var attack = Math.max(1, opts.attack != null ? opts.attack : 5);
  var release = Math.max(1, opts.release != null ? opts.release : 50);
  var mu = Math.pow(10, makeup/20);
  var env = 0;
  var out = new Array(samples.length);
  for(var i=0;i<samples.length;i++){
    var lvl = Math.abs(samples[i]);
    var coeff = lvl > env ? (1/attack) : (1/release);
    env = env + coeff*(lvl - env);
    var lvlDb = 20*Math.log10(env + 1e-9);
    var gainDb = 0;
    if(lvlDb > thr){ gainDb = (thr - lvlDb)*(1 - 1/ratio); }
    out[i] = samples[i] * Math.pow(10, gainDb/20) * mu;
  }
  return out;
}
function compressAnalyze(samples, opts){
  var out = compressProcess(samples, opts);
  var peak=0, sum=0;
  for(var i=0;i<out.length;i++){ var a=Math.abs(out[i]); if(a>peak)peak=a; sum+=out[i]*out[i]; }
  var thr = opts.threshold != null ? opts.threshold : -20;
  var ratio = opts.ratio != null ? opts.ratio : 4;
  var maxRed = 0;
  for(var i=0;i<samples.length;i++){
    var lvlDb = 20*Math.log10(Math.abs(samples[i]) + 1e-9);
    if(lvlDb > thr){ var red=(lvlDb-thr)*(1-1/ratio); if(red>maxRed) maxRed=red; }
  }
  return { length: out.length, peak: peak, rms: Math.sqrt(sum/out.length), maxReductionDb: Math.round(maxRed*100)/100 };
}

var EXPORTS={compressAnalyze:compressAnalyze,compressProcess:compressProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CompressorForgePure = EXPORTS; }
